return items.map(item => {
  const event = item.json;
  const payload = event.payload || {};

  const fields = payload.fields || {};
  const utm = payload.utm || {};

  const leadEmail = fields.email
    ? fields.email.toLowerCase().trim()
    : null;

  const leadPhone = fields.phone
    ? fields.phone.replace(/[^\d+]/g, '')
    : null;

  const leadName = fields.name
    ? fields.name.trim()
    : null;

  return {
    json: {
      event_id: event.internal_id,
      event_external_id: event.external_id,

      retry_count: event.retry_count || 0,

      lead_name: leadName,
      lead_email: leadEmail,
      lead_phone: leadPhone,
      lead_source: utm.utm_source || 'unknown',

      raw_event: event,

      is_valid: Boolean(leadEmail && leadName),

      validation_errors: [
        !leadEmail ? 'missing_email' : null,
        !leadName ? 'missing_name' : null
      ].filter(Boolean)
    }
  };
});

return items.map(item => {
  const lead = item.json;

  const shouldFail = true;

  if (shouldFail) {
    return {
      json: {
        ...lead,

        crm_success: false,
        crm_error: true,
        crm_status_code: 503,
        crm_error_message: 'Mock CRM API error during retry: temporary unavailable',

        crm_response: {
          success: false,
          status_code: 503,
          error: {
            code: 'SERVICE_UNAVAILABLE',
            message: 'Mock CRM API error during retry: temporary unavailable',
            type: 'temporary_error'
          },
          request_id: `req_${Date.now()}_${Math.floor(Math.random() * 10000)}`,
          timestamp: new Date().toISOString()
        }
      }
    };
  }

  const crmContactId = `crm_retry_${Date.now()}_${Math.floor(Math.random() * 10000)}`;

  return {
    json: {
      ...lead,

      crm_success: true,
      crm_error: false,
      crm_status_code: 201,
      lead_external_id: crmContactId,

      crm_response: {
        success: true,
        status_code: 201,
        data: {
          crm_contact_id: crmContactId,
          crm_status: 'created',
          crm_created_at: new Date().toISOString()
        },
        request_id: `req_${Date.now()}_${Math.floor(Math.random() * 10000)}`,
        timestamp: new Date().toISOString()
      }
    }
  };
});

